 "content": "def transform(grid):
    """Extend each diagonal pair of matching non-background cells as a ray."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                # Continue away from the pair at both ends, stopping at any object.
                for rr, cc, sr, sc in ((r - dr, c - dc, -dr, -dc),
                                        (r2 + dr, c2 + dc, dr, dc)):
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
